CREATE TYPE public.app_role AS ENUM ('admin','customer');
CREATE OR REPLACE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE OR REPLACE FUNCTION public.create_signup_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES (NEW.id); RETURN NEW; END $$;
CREATE TRIGGER signup_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_signup_profile();
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated, service_role;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.categories TO anon,authenticated; GRANT ALL ON public.categories TO service_role; GRANT INSERT,UPDATE,DELETE ON public.categories TO authenticated;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_read ON public.categories FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY categories_admin_all ON public.categories FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TRIGGER categories_updated BEFORE UPDATE ON public.categories FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.collections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, description text NOT NULL DEFAULT '', published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.collections TO anon,authenticated; GRANT ALL ON public.collections TO service_role; GRANT INSERT,UPDATE,DELETE ON public.collections TO authenticated;
ALTER TABLE public.collections ENABLE ROW LEVEL SECURITY;
CREATE POLICY collections_public ON public.collections FOR SELECT TO anon,authenticated USING (published);
CREATE POLICY collections_admin ON public.collections FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TRIGGER collections_updated BEFORE UPDATE ON public.collections FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, gender text NOT NULL CHECK (gender IN ('kadin','erkek')), category_id uuid NOT NULL REFERENCES public.categories(id), description text NOT NULL DEFAULT '', fabric text NOT NULL DEFAULT '', fit text NOT NULL DEFAULT '', care text NOT NULL DEFAULT '', price numeric(12,2) NOT NULL DEFAULT 0 CHECK (price>=0), sale_price numeric(12,2) CHECK (sale_price IS NULL OR sale_price>=0), sizes text[] NOT NULL DEFAULT ARRAY[]::text[], colors jsonb NOT NULL DEFAULT '[]'::jsonb, published boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, new_arrival boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_public ON public.products FOR SELECT TO anon,authenticated USING (published);
CREATE POLICY products_admin ON public.products FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TRIGGER products_updated BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.product_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, url text NOT NULL, alt text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.product_images TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.product_images TO authenticated; GRANT ALL ON public.product_images TO service_role;
ALTER TABLE public.product_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY images_public ON public.product_images FOR SELECT TO anon,authenticated USING (EXISTS (SELECT 1 FROM public.products p WHERE p.id=product_id AND p.published));
CREATE POLICY images_admin ON public.product_images FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.product_variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, color text NOT NULL, size text NOT NULL, sku text UNIQUE, inventory integer NOT NULL DEFAULT 0 CHECK (inventory>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id,color,size));
GRANT SELECT ON public.product_variants TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.product_variants TO authenticated; GRANT ALL ON public.product_variants TO service_role;
ALTER TABLE public.product_variants ENABLE ROW LEVEL SECURITY;
CREATE POLICY variants_public ON public.product_variants FOR SELECT TO anon,authenticated USING (EXISTS (SELECT 1 FROM public.products p WHERE p.id=product_id AND p.published));
CREATE POLICY variants_admin ON public.product_variants FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TRIGGER variants_updated BEFORE UPDATE ON public.product_variants FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.product_collections (product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, collection_id uuid NOT NULL REFERENCES public.collections(id) ON DELETE CASCADE, PRIMARY KEY(product_id,collection_id));
GRANT SELECT ON public.product_collections TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.product_collections TO authenticated; GRANT ALL ON public.product_collections TO service_role;
ALTER TABLE public.product_collections ENABLE ROW LEVEL SECURITY;
CREATE POLICY product_collections_public ON public.product_collections FOR SELECT TO anon,authenticated USING (EXISTS (SELECT 1 FROM public.products p WHERE p.id=product_id AND p.published) AND EXISTS (SELECT 1 FROM public.collections c WHERE c.id=collection_id AND c.published));
CREATE POLICY product_collections_admin ON public.product_collections FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.favorites (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,product_id));
GRANT SELECT,INSERT,DELETE ON public.favorites TO authenticated; GRANT ALL ON public.favorites TO service_role;
ALTER TABLE public.favorites ENABLE ROW LEVEL SECURITY;
CREATE POLICY favorites_own ON public.favorites FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.carts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.carts TO authenticated; GRANT ALL ON public.carts TO service_role;
ALTER TABLE public.carts ENABLE ROW LEVEL SECURITY;
CREATE POLICY carts_own ON public.carts FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TRIGGER carts_updated BEFORE UPDATE ON public.carts FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.cart_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cart_id uuid NOT NULL REFERENCES public.carts(id) ON DELETE CASCADE, variant_id uuid NOT NULL REFERENCES public.product_variants(id), quantity integer NOT NULL DEFAULT 1 CHECK (quantity>0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cart_id,variant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cart_items TO authenticated; GRANT ALL ON public.cart_items TO service_role;
ALTER TABLE public.cart_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY cart_items_own ON public.cart_items FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.carts c WHERE c.id=cart_id AND c.user_id=auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.carts c WHERE c.id=cart_id AND c.user_id=auth.uid()));
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','paid','shipped','delivered','cancelled')), total numeric(12,2) NOT NULL DEFAULT 0 CHECK (total>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated; GRANT INSERT,UPDATE,DELETE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY orders_own_read ON public.orders FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY orders_admin ON public.orders FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TRIGGER orders_updated BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id), variant_id uuid REFERENCES public.product_variants(id), quantity integer NOT NULL CHECK (quantity>0), unit_price numeric(12,2) NOT NULL CHECK (unit_price>=0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.order_items TO authenticated; GRANT ALL ON public.order_items TO service_role;
ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY order_items_own_read ON public.order_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.orders o WHERE o.id=order_id AND o.user_id=auth.uid()));
CREATE POLICY order_items_admin ON public.order_items FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.product_views (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, viewed_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.product_views TO anon,authenticated; GRANT SELECT ON public.product_views TO authenticated; GRANT ALL ON public.product_views TO service_role; GRANT USAGE ON SEQUENCE public.product_views_id_seq TO anon,authenticated,service_role;
ALTER TABLE public.product_views ENABLE ROW LEVEL SECURITY;
CREATE POLICY product_views_public_write ON public.product_views FOR INSERT TO anon,authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.products p WHERE p.id=product_id AND p.published));
CREATE POLICY product_views_admin_read ON public.product_views FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.page_views (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, path text NOT NULL CHECK (path ~ '^/(kadin|erkek|koleksiyon|yeni-gelenler|hakkimizda|urun)$'), viewed_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.page_views TO anon,authenticated; GRANT SELECT ON public.page_views TO authenticated; GRANT ALL ON public.page_views TO service_role; GRANT USAGE ON SEQUENCE public.page_views_id_seq TO anon,authenticated,service_role;
ALTER TABLE public.page_views ENABLE ROW LEVEL SECURITY;
CREATE POLICY page_views_public_write ON public.page_views FOR INSERT TO anon,authenticated WITH CHECK (path ~ '^/(kadin|erkek|koleksiyon|yeni-gelenler|hakkimizda|urun)$');
CREATE POLICY page_views_admin_read ON public.page_views FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE INDEX product_views_product_idx ON public.product_views(product_id);
CREATE INDEX order_items_product_idx ON public.order_items(product_id);
CREATE INDEX page_views_path_idx ON public.page_views(path);